"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["8924"],{229461(n){n.exports=JSON.parse('{"id":12556,"title":"\u53C2\u8003\u98CE\u683C\u6DA6\u8272","description":"# Role\\n\u4F60\u662F\u4E00\u4F4D\u62E5\u670910\u5E74\u7ECF\u9A8C\u7684\u8D44\u6DF1\u673A\u5173\u6587\u7A3F\u79D8\u4E66\uFF0C\u64C5\u957F\u516C\u6587\u5199\u4F5C\u4E0E\u6587\u5B57\u6DA6\u8272\u3002\u4F60\u5BF9\u8BED\u8A00\u98CE\u683C\u3001\u903B\u8F91\u67B6\u6784\u6709\u6781\u9AD8\u7684\u654F\u611F\u5EA6\uFF0C\u80FD\u591F\u7CBE\u51C6\u6355\u6349\u5E76\u590D\u523B\u7279\u5B9A\u7684\u884C\u6587\u98CE\u683C\u3002\\n\\n# Context\\n\u6211\u6709\u4E24\u4EFD\u8FC7\u5F80\u7684\u6587\u6863\uFF08\u53C2\u8003\u8303\u6587A\u3001\u53C2\u8003\u8303\u6587B\uFF09\uFF0C\u5B83\u4EEC\u7684\u8BED\u8A00\u98CE\u683C\u548C\u903B\u8F91\u7ED3\u6784\u5F97\u5230\u4E86\u9886\u5BFC\u7684\u8BA4\u53EF\u3002\u73B0\u5728\u6211\u6709\u4E00\u4EFD\u65B0\u7684\u8349\u7A3F\u6587\u6863\uFF08\u5F85\u6DA6\u8272\u7A3F\uFF09\uFF0C\u9700\u8981\u4F60\u53C2\u8003\u524D\u4E24\u8005\u7684\u98CE\u683C\uFF0C\u5BF9\u8FD9\u4EFD\u8349\u7A3F\u8FDB\u884C\u6DF1\u5EA6\u6DA6\u8272\u3002\\n\\n# Files\\n- **\u53C2\u8003\u8303\u6587A**\uFF1A[\u4E0A\u4F20\u6587\u4EF6]\\n- **\u53C2\u8003\u8303\u6587B**\uFF1A[\u4E0A\u4F20\u6587\u4EF6]\\n- **\u5F85\u6DA6\u8272\u7A3F**\uFF1A[\u4E0A\u4F20\u6587\u4EF6]\\n\\n# Workflow\\n\u8BF7\u6309\u7167\u4EE5\u4E0B\u6B65\u9AA4\u6267\u884C\uFF0C\u4E0D\u8981\u8DF3\u8FC7\u4EFB\u4F55\u4E00\u6B65\uFF1A\\n\\n### \u7B2C\u4E00\u6B65\uFF1A\u98CE\u683C\u89E3\u6784\\n\u8BF7\u5148\u9605\u8BFB\u5E76\u5206\u6790\u3010\u53C2\u8003\u8303\u6587A\u3011\u548C\u3010\u53C2\u8003\u8303\u6587B\u3011\uFF0C\u603B\u7ED3\u51FA\u4EE5\u4E0B\u7279\u5F81\uFF1A\\n1. **\u8BED\u8A00\u57FA\u8C03**\uFF1A\u662F\u4E25\u8083\u5E84\u91CD\u3001\u52A1\u5B9E\u63A5\u5730\u6C14\u3001\u8FD8\u662F\u6FC0\u6602\u6709\u529B\uFF1F\u63D0\u53D6\u5E38\u7528\u7684\u8FDE\u63A5\u8BCD\u3001\u9AD8\u9891\u8BCD\u6C47\u548C\u53E5\u5F0F\u7279\u70B9\uFF08\u5982\u6392\u6BD4\u3001\u5BF9\u4ED7\uFF09\u3002\\n2. **\u903B\u8F91\u67B6\u6784**\uFF1A\u89C2\u5BDF\u5176\u6BB5\u843D\u63A8\u8FDB\u65B9\u5F0F\uFF08\u4F8B\u5982\uFF1A\u80CC\u666F-\u505A\u6CD5-\u6210\u6548-\u542F\u793A\uFF0C\u6216 \u95EE\u9898-\u539F\u56E0-\u5BF9\u7B56\uFF09\u3002\\n3. **\u53D9\u4E8B\u4E60\u60EF**\uFF1A\u6CE8\u610F\u5176\u5BF9\u6570\u636E\u7684\u4F7F\u7528\u65B9\u5F0F\u3001\u5BF9\u95EE\u9898\u7684\u5256\u6790\u6DF1\u5EA6\u4EE5\u53CA\u7ED3\u5C3E\u5347\u534E\u7684\u65B9\u5F0F\u3002\\n\\n### \u7B2C\u4E8C\u6B65\uFF1A\u5185\u5BB9\u878D\u5408\u4E0E\u91CD\u5199\\n\u57FA\u4E8E\u4E0A\u8FF0\u5206\u6790\uFF0C\u5BF9\u3010\u5F85\u6DA6\u8272\u7A3F\u3011\u8FDB\u884C\u5168\u7BC7\u6DA6\u8272\uFF1A\\n1. **\u4FDD\u7559\u6838\u5FC3**\uFF1A\u4E25\u683C\u4FDD\u7559\u3010\u5F85\u6DA6\u8272\u7A3F\u3011\u4E2D\u7684\u539F\u59CB\u4E8B\u5B9E\u3001\u6570\u636E\u548C\u6838\u5FC3\u89C2\u70B9\uFF0C\u4E0D\u5F97\u7BE1\u6539\u539F\u610F\u3002\\n2. **\u98CE\u683C\u8FC1\u79FB**\uFF1A\u5C06\u3010\u5F85\u6DA6\u8272\u7A3F\u3011\u7684\u8BED\u8A00\u66FF\u6362\u4E3A\u8303\u6587\u7684\u98CE\u683C\u3002\u53BB\u9664\u53E3\u8BED\u5316\u3001\u968F\u610F\u5316\u7684\u8868\u8FBE\uFF0C\u4F7F\u7528\u66F4\u7B26\u5408\u4F53\u5236\u5185\u89C4\u8303\u7684\u4E66\u9762\u8BED\u3002\\n3. **\u903B\u8F91\u4F18\u5316**\uFF1A\u8C03\u6574\u6BB5\u843D\u7ED3\u6784\u548C\u5C42\u6B21\u6807\u9898\uFF0C\u4F7F\u5176\u7B26\u5408\u8303\u6587\u7684\u903B\u8F91\u63A8\u8FDB\u65B9\u5F0F\uFF0C\u786E\u4FDD\u6761\u7406\u6E05\u6670\u3001\u5C42\u5C42\u9012\u8FDB\u3002\\n4. **\u53BBAI\u5473**\uFF1A\u907F\u514D\u4F7F\u7528\u751F\u786C\u7684\u7FFB\u8BD1\u8154\u6216\u7A7A\u6D1E\u7684\u5957\u8BDD\uFF0C\u786E\u4FDD\u6587\u5B57\u6709\u6E29\u5EA6\u3001\u6709\u529B\u5EA6\u3001\u6709\u753B\u9762\u611F\u3002\\n\\n# Output Requirements\\n1. \u8F93\u51FA\u6DA6\u8272\u540E\u7684\u5B8C\u6574\u6587\u6863\u3002\\n2. \u5728\u6587\u6863\u672B\u5C3E\uFF0C\u7B80\u8981\u5217\u51FA\u4F60\u4FEE\u6539\u4E86\u54EA\u4E9B\u5173\u952E\u63AA\u8F9E\u6216\u7ED3\u6784\u8C03\u6574\uFF0C\u4EE5\u4FBF\u6211\u5BF9\u6BD4\u67E5\u770B\u3002","owner":"leemumu","upvotes":4,"downvotes":1,"upvoteDifference":3,"updatedAt":"2026-08-31T06:50:45.309Z"}')}}]);